[{"type":"text","text":"# 门户H5 本地部署 —— nginx 站点 (root 指向 D:/repository/门户H5/dist)
# 独立站点，与「门户」(8092) 互不干扰。
# API 代理复用 门户 的 v2 dev 网关（与 门户.conf 一致）。
# 代理对齐 env VITE_APP_PROXY_ADDRESS（v2 网关）

server {
    listen 8091;
    server_name localhost;
    root D:/repository/门户H5/dist;
    index index.html;
    charset utf-8;
    client_max_body_size 100m;

    # ---- 弱网优化：文本资源压缩（放在 server 内，避免与门户.conf 的 http 级 gzip 重复）----
    # 只压缩文本类资源（图片/字体已是二进制，压缩反而浪费 CPU）。
    gzip on;
    gzip_comp_level 5;
    gzip_min_length 1024;
    gzip_vary on;
    gzip_proxied any;
    gzip_http_version 1.1;
    gzip_types
        text/plain
        text/css
        text/xml
        text/javascript
        application/javascript
        application/json
        application/manifest+json
        application/xml
        application/rss+xml
        application/atom+xml
        image/svg+xml
        font/ttf
        font/otf;

    # 代理公共配置（以下所有 proxy_pass location 继承）
    proxy_http_version 1.1;
    proxy_set_header Connection "";
    proxy_set_header Host 127.0.0.1:8086;
    proxy_set_header X-Real-IP $remote_addr;
    proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
    proxy_set_header X-Forwarded-Proto $scheme;
    proxy_connect_timeout 60s;
    proxy_send_timeout 120s;
    proxy_read_timeout 120s;

    # 静态资源缓存（文件名带内容 hash，可长缓存）
    location ~* \.(js|css|png|jpg|jpeg|gif|ico|svg|woff|woff2|ttf|eot|map|xlsx|json)$ {
        add_header Cache-Control "public, max-age=2592000, immutable" always;
        access_log off;
        try_files $uri =404;
    }
    location = /index.html {
        expires -1;
        add_header Cache-Control "no-cache, no-store, must-revalidate";
        add_header Pragma "no-cache";
    }
    # 站点版本号（前端发版检测用）：不缓存
    location = /version.json {
        add_header Cache-Control "no-cache, no-store, must-revalidate";
    }

    # 业务 API（v2 dev 网关：保留 /api/v2.0、/api/v3.0 前缀）
    location /api/v2.0/ {
        # 网关路由本身不含 /api 前缀（生产由入口层剥离），本地代理时此处补剥 /api
        proxy_pass http://127.0.0.1:8086/v2.0/;
